grid = [[int(x) for x in row.split()] for row in grid_str.strip().split('\n')]

# Identify regions separated by 0s
regions = []
for r in range(len(grid)):
    row_data = []
    c = 0
    while c < len(grid[0]):
        if grid[r][c] == 0:
            c += 1
        else:
            start_c = c
            while c < len(grid[0]) and grid[r][c] != 0:
                c += 1
            row_data.append((start_c, c-start_c))
    regions.append(row_data)

print("Row segments (col_start, length):")
for r, segs in enumerate(regions[:5]):
    print(f"Row {r}: {segs}")

# Try hypothesis: fill each connected component's bounding box with 3s
from collections import deque

grid = [[int(x) for x in row.split()] for row in grid_str.strip().split('\n')]
rows = len(grid)
cols = len(grid[0])

visited = set()

def get_component(r, c):
    comp = []
    queue = deque([(r, c)])
    visited.add((r, c))

    while queue:
        cr, cc = queue.popleft()
        comp.append((cr, cc))
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] != 0 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
    return comp

output = [row[:] for row in grid]  # start with copy

for r in range(rows):
    for c in range(cols):
        if grid[r][c] != 0 and (r, c) not in visited:
            comp = get_component(r, c)
            min_r = min(r for r, c in comp)
            max_r = max(r for r, c in comp)
            min_c = min(c for r, c in comp)
            max_c = max(c for r, c in comp)

            # Fill bounding box with 3s
            for rr in range(min_r, max_r + 1):
                for cc in range(min_c, max_c + 1):
                    output[rr][cc] = 3

print("Hypothesis: fill each component's bounding box with 3s")
for i, row in enumerate(output):
    print(f"Row {i}: {row}")

